    Type[] arguments = paramType.getActualTypeArguments(); 
    Class<?>[] resolvedArguments = new Class<?>[arguments.length]; 
    for (int i = 0; i < arguments.length; i++) { 
        if (arguments[i] instanceof TypeVariable) { 
            Map<TypeVariable<?>, Type> typeVariableMap = getTypeVariableMap(targetType); 
            TypeVariable<?> typeVariable = (TypeVariable<?>) arguments[i]; 
            Type resolvedType = typeVariableMap.get(typeVariable); 
            if (resolvedType instanceof Class<?>) { 
                resolvedArguments[i] = (Class<?>) resolvedType; 
            } else { 
                return null; 
            } 
        } else if (arguments[i] instanceof Class<?>) { 
            resolvedArguments[i] = (Class<?>) arguments[i]; 
        } else { 
            return null; 
        } 
    } 
    return resolvedArguments; 
