Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
        for (int i = 0; i < actualTypeArguments.length; i++) {
            Type typeArgument = actualTypeArguments[i];
            if (typeArgument instanceof Class<?>) {
                resolvedArguments[i] = (Class<?>) typeArgument;
            } else if (typeArgument instanceof TypeVariable<?>) {
                Class<?> resolvedType = resolveTypeVariable(targetType, (TypeVariable<?>) typeArgument);
                if (resolvedType != null) {
                    resolvedArguments[i] = resolvedType;
                } else {
                    return null; // If any type variable cannot be resolved, return null
                }
            } else {
                return null; // If the type argument is not a class or type variable, return null
            }
        }
        return resolvedArguments;
    }
    return null; // If the genericType is not parameterized, return null
}

Class<?> resolveTypeVariable(Class<?> targetType, TypeVariable<?> typeVariable) {
    Map<TypeVariable<?>, Type> typeVariableMap = getTypeVariableMap(targetType);
    Type resolvedType = typeVariableMap.get(typeVariable);
    if (resolvedType instanceof Class<?>) {
        return (Class<?>) resolvedType;
    } else if (resolvedType instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) resolvedType).getRawType();
    }
    return null;
}

Map<TypeVariable<?>, Type> getTypeVariableMap(Class<?> targetType) {
    Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
    Type genericSuperclass = targetType.getGenericSuperclass();
    if (genericSuperclass instanceof ParameterizedType) {
        ParameterizedType parameterizedSuperclass = (ParameterizedType) genericSuperclass;
        Type[] actualTypeArguments = parameterizedSuperclass.getActualTypeArguments();
        TypeVariable<?>[] typeParameters = ((Class<?>) parameterizedSuperclass.getRawType()).getTypeParameters();
        for (int i = 0; i < typeParameters.length; i++) {
            typeVariableMap.put(typeParameters[i], actualTypeArguments[i]);
        }
    }
    for (Type genericInterface : targetType.getGenericInterfaces()) {
        if (genericInterface instanceof ParameterizedType) {
            ParameterizedType parameterizedInterface = (ParameterizedType) genericInterface;
            Type[] actualTypeArguments = parameterizedInterface.getActualTypeArguments();
            TypeVariable<?>[] typeParameters = ((Class<?>) parameterizedInterface.getRawType()).getTypeParameters();
            for (int i = 0; i < typeParameters.length; i++) {
                typeVariableMap.put(typeParameters[i], actualTypeArguments[i]);
            }
        }
    }
    return typeVariableMap;
}

