List<PathSegmentImpl> function ( URI u , boolean decode ) { 
    String path = u.getRawPath();
    if (path == null || path.isEmpty()) {
        return Collections.emptyList();
    }
    if (path.charAt(0) == '/') {
        path = path.substring(1);
    }
    List<PathSegmentImpl> segments = new ArrayList<>();
    String[] parts = path.split("/");
    for (String part : parts) {
        if (decode) {
            try {
                part = URLDecoder.decode(part, "UTF-8");
            } catch (UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(part, null));
    }
    return segments;
}

List<PathSegmentImpl> function(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = u.getRawPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }

    // If the path is absolute, skip the leading '/'
    int start = path.startsWith("/") ? 1 : 0;

    int end;
    while (start < path.length()) {
        end = path.indexOf('/', start);
        if (end == -1) {
            end = path.length();
        }

        String segment = path.substring(start, end);
        if (decode) {
            segment = URLDecoder.decode(segment, StandardCharsets.UTF_8);
        }

        segments.add(new PathSegmentImpl(segment, false));

        start = end + 1;
    }

    return segments;
}

