    }
    StringBuilder sb = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (++i >= len) {
                throw new Exception("Invalid escape sequence");
            }
            c = str.charAt(i);
            switch (c) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '"':
                    sb.append('"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    if (i + 4 >= len) {
                        throw new Exception("Invalid unicode escape sequence");
                    }
                    int codepoint = 0;
                    for (int j = 0; j < 4; j++) {
                        char h = str.charAt(++i);
                        if (h >= '0' && h <= '9') {
                            codepoint = (codepoint << 4) + h - '0';
                        } else if (h >= 'a' && h <= 'f') {
                            codepoint = (codepoint << 4) + 10 + h - 'a';
                        } else if (h >= 'A' && h <= 'F') {
                            codepoint = (codepoint << 4) + 10 + h - 'A';
                        } else {
                            throw new Exception("Invalid unicode escape sequence");
                        }
                    }
                    sb.append((char) codepoint);
                    break;
                default:
                    throw new Exception("Invalid escape sequence");
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

