GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> pathEdges = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(pathEdges.get(0));
    List<V> pathVertices = new ArrayList<>();
    pathVertices.add(startVertex);

    while (!pathEdges.isEmpty()) {
        E currentEdge = null;
        for (E edge : pathEdges) {
            if (graph.getEdgeSource(edge).equals(pathVertices.get(pathVertices.size() - 1)) ||
                graph.getEdgeTarget(edge).equals(pathVertices.get(pathVertices.size() - 1))) {
                currentEdge = edge;
                break;
            }
        }
        if (currentEdge != null) {
            V nextVertex = graph.getEdgeSource(currentEdge).equals(pathVertices.get(pathVertices.size() - 1)) ?
                           graph.getEdgeTarget(currentEdge) : graph.getEdgeSource(currentEdge);
            pathVertices.add(nextVertex);
            pathEdges.remove(currentEdge);
        }
    }

    return new GraphPathImpl<>(graph, startVertex, pathVertices.get(pathVertices.size() - 1), pathEdges, pathVertices);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<V> vertexList = new ArrayList<>();
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, vertexList, 0);
    }

    Map<V, Set<E>> vertexToEdges = new HashMap<>();
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        vertexToEdges.computeIfAbsent(source, k -> new HashSet<>()).add(edge);
        vertexToEdges.computeIfAbsent(target, k -> new HashSet<>()).add(edge);
    }

    V startVertex = null;
    for (Map.Entry<V, Set<E>> entry : vertexToEdges.entrySet()) {
        if (entry.getValue().size() == 1) {
            startVertex = entry.getKey();
            break;
        }
    }

    if (startVertex == null) {
        startVertex = graph.vertexSet().iterator().next(); // Fallback, should not happen in a valid tour
    }

    V currentVertex = startVertex;
    while (currentVertex != null) {
        vertexList.add(currentVertex);
        E nextEdge = vertexToEdges.get(currentVertex).iterator().next();
        vertexToEdges.get(currentVertex).remove(nextEdge);
        V nextVertex;
        if (graph.getEdgeSource(nextEdge) == currentVertex) {
            nextVertex = graph.getEdgeTarget(nextEdge);
        } else {
            nextVertex = graph.getEdgeSource(nextEdge);
        }
        vertexToEdges.get(nextVertex).remove(nextEdge);
        if (vertexToEdges.get(nextVertex).isEmpty()) {
            vertexToEdges.remove(nextVertex);
            if (vertexToEdges.isEmpty()) {
                break;
            }
        }
        currentVertex = nextVertex;
    }

    double weight = 0;
    for (E edge : tour) {
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, startVertex, vertexList, weight);
}

GraphPath<V, E> function(Set<E> tour, Graph<V, E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = null;
    V currentVertex = null;

    // Find a starting vertex
    for (E edge : edgeList) {
        startVertex = graph.getEdgeSource(edge);
        currentVertex = startVertex;
        break;
    }

    // Build the path
    List<E> pathEdges = new ArrayList<>();
    while (!edgeList.isEmpty()) {
        for (Iterator<E> it = edgeList.iterator(); it.hasNext(); ) {
            E edge = it.next();
            if (graph.getEdgeSource(edge) == currentVertex || graph.getEdgeTarget(edge) == currentVertex) {
                pathEdges.add(edge);
                currentVertex = (graph.getEdgeSource(edge) == currentVertex) ? graph.getEdgeTarget(edge) : graph.getEdgeSource(edge);
                it.remove();
            }
        }
    }

    return new GraphPathImpl<>(graph, startVertex, currentVertex, pathEdges, 0);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edges = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(edges.get(0));
    List<V> vertexPath = new ArrayList<>();
    vertexPath.add(startVertex);

    Set<E> edgesUsed = new HashSet<>();
    V currentVertex = startVertex;

    while (edgesUsed.size() < edges.size()) {
        for (E edge : edges) {
            if (!edgesUsed.contains(edge) && graph.getEdgeSource(edge).equals(currentVertex)) {
                vertexPath.add(graph.getEdgeTarget(edge));
                currentVertex = graph.getEdgeTarget(edge);
                edgesUsed.add(edge);
                break;
            } else if (!edgesUsed.contains(edge) && graph.getEdgeTarget(edge).equals(currentVertex)) {
                vertexPath.add(graph.getEdgeSource(edge));
                currentVertex = graph.getEdgeSource(edge);
                edgesUsed.add(edge);
                break;
            }
        }
    }

    return new GraphPathImpl<>(graph, startVertex, currentVertex, vertexPath, edges, 0.0);
}

