String applyRelativePath(String path, String relativePath) {
    // Normalize the paths by removing any trailing slashes
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Use a list to handle the path components
    List<String> pathList = new ArrayList<>(Arrays.asList(pathComponents));

    // Process each component of the relative path
    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            // Move up one directory if possible
            if (pathList.size() > 1) {
                pathList.remove(pathList.size() - 1);
            }
        } else if (!component.equals(".")) {
            // Add the component if it's not a current directory reference
            pathList.add(component);
        }
    }

    // Join the path components back into a single string
    return String.join("/", pathList);
}

