String function ( String path , String relativePath ) { 
    if ( path == null || relativePath == null ) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }
    String[] parts = path.split("/");
    String[] relativeParts = relativePath.split("/");

    int lastIndex = parts.length - 1;
    if (parts[lastIndex].isEmpty()) {
        lastIndex--; // Adjust in case of trailing slash
    }

    for (String part : relativeParts) {
        if (part.equals("..")) {
            if (lastIndex > 0) {
                lastIndex--;
            }
        } else if (!part.equals(".")) {
            parts[++lastIndex] = part;
        }
    }

    StringBuilder result = new StringBuilder();
    for (int i = 0; i <= lastIndex; i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(parts[i]);
    }

    return result.toString(); 
}

